# TableBook: a tiny web app for small restaurants to track daily covers, sales and staff shifts.
from http.server import BaseHTTPRequestHandler, HTTPServer
import json

SALES = []

PAGE = """<!doctype html><html><head><title>TableBook</title></head><body>
<h1>TableBook</h1>
<form id=f><input id=covers placeholder="covers" type=number>
<input id=sales placeholder="sales $" type=number step=0.01>
<button>Add day</button></form>
<table border=1><thead><tr><th>Day</th><th>Covers</th><th>Sales</th><th>Sales/cover</th></tr></thead>
<tbody id=rows></tbody></table>
<script>
async function load(){const r=await fetch('/api/days');const d=await r.json();
document.getElementById('rows').innerHTML=d.map((x,i)=>`<tr><td>${i+1}</td><td>${x.covers}</td><td>${x.sales.toFixed(2)}</td><td>${(x.sales/x.covers).toFixed(2)}</td></tr>`).join('');}
document.getElementById('f').onsubmit=async e=>{e.preventDefault();
await fetch('/api/days',{method:'POST',headers:{'Content-Type':'application/json'},
body:JSON.stringify({covers:+covers.value,sales:+sales.value})});load();};
load();
</script></body></html>"""

def summarize(days):
    total_cov = sum(d["covers"] for d in days)
    total_sales = sum(d["sales"] for d in days)
    per_cover = total_sales / total_cov if total_cov else 0.0
    return {"days": len(days), "covers": total_cov, "sales": round(total_sales, 2),
            "avg_sales_per_cover": round(per_cover, 2)}

class H(BaseHTTPRequestHandler):
    def _send(self, code, body, ctype="application/json"):
        data = body.encode() if isinstance(body, str) else json.dumps(body).encode()
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if self.path == "/":
            self._send(200, PAGE, "text/html")
        elif self.path == "/api/days":
            self._send(200, SALES)
        elif self.path == "/api/summary":
            self._send(200, summarize(SALES))
        else:
            self._send(404, {"error": "not found"})

    def do_POST(self):
        if self.path != "/api/days":
            return self._send(404, {"error": "not found"})
        n = int(self.headers.get("Content-Length", 0))
        try:
            body = json.loads(self.rfile.read(n) or b"{}")
            covers = int(body["covers"]); sales = float(body["sales"])
            if covers <= 0 or sales < 0:
                raise ValueError("covers must be >0 and sales >=0")
        except (KeyError, ValueError, TypeError) as e:
            return self._send(400, {"error": str(e)})
        SALES.append({"covers": covers, "sales": sales})
        self._send(201, SALES[-1])

if __name__ == "__main__":
    HTTPServer(("127.0.0.1", 8000), H).serve_forever()
EOF
